    {
      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-novel-forge\",\n  \"version\": \"1.6.1\",\n  \"description\": \"AI 写长篇的四个死法：设定崩、看不见前文、水文超字数、满屏 AI 味——这个插件全用代码堵死。细纲不批准就不给写章，设定改值直接拒绝，重复句段机审拦下，六维去 AI 味扫描零 token。右侧栏锻炉面板带听书、全书体检、批量起草断点续跑；23 个 novel_* 工具，你只管讲故事，把关交给代码。Novel-writing guardrails plugin for DeepSeek Harness (DSH).\",\n  \"keywords\": [\n    \"deepseek\",\n    \"deepseek-harness\",\n    \"dsh\",\n    \"dsh-plugin\",\n    \"novel-writing\",\n    \"ai-writing\",\n    \"creative-writing\",\n    \"小说\",\n    \"网文\",\n    \"连载\",\n    \"起点\",\n    \"番茄\",\n    \"去AI味\"\n  ],\n  \"license\": \"MIT\",\n  \"author\": \"huangziyuan-general\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/huangziyuan-general/dsh-novel-forge.git\"\n  },\n  \"type\": \"module\",\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\"\n  },\n  \"main\": \"./lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"CHANGELOG.md\",\n    \"COMPATIBILITY.md\",\n    \"README.md\",\n    \"README.en.md\",\n    \"cordis.patch.yml\",\n    \"lib\",\n    \"mcp\",\n    \"skills\"\n  ],\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh-fs\": \"*\",\n    \"@deepseek-ai/dsh-tools\": \"*\",\n    \"@deepseek-ai/schemastery\": \"*\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-fs\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-tools\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/schemastery\": {\n      \"optional\": true\n    }\n  },\n  \"scripts\": {\n    \"build\": \"node scripts/build-client.mjs\",\n    \"audit\": \"node scripts/audit-static.mjs && node scripts/audit-lib-calls.mjs\",\n    \"preview\": \"npm run build && node scripts/preview-ui.mjs\",\n    \"pretest\": \"npm run build && npm run audit\",\n    \"test\": \"node --test test/*.test.mjs\",\n    \"setup-dev\": \"node scripts/setup-dev-links.mjs\",\n    \"realboot\": \"node scripts/real-boot-test.mjs\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\"\n    }\n  },\n  \"bin\": {\n    \"dsh-novel-forge-mcp\": \"./mcp/server.mjs\"\n  },\n  \"devDependencies\": {\n    \"esbuild\": \"^0.28.2\"\n  }\n}\n"
    },
    {
      "path": "lib/tools/writing-tools.js",
      "content": "// lib/tools/writing-tools.js — novel_briefing / novel_write_chapter。\n// briefing 组装上下文包（一致性供给侧）；write_chapter 只是**入口**——真正的硬约束链\n// （阶段门禁 → 细纲存在性 → 机审 → 账本冲突 → 内容门禁 → 契约指标 → 版本落盘 → 审计）\n// 在 lib/chapter-commit.js，与 D2 并发批量起草**共用同一条**，两者不可能漂移。\n\nimport { defineTool } from './define-tool.js';\nimport { pathsFor, effectiveCharConfig, platformLimitsText } from '../store.js';\nimport { assertBookName, createFsio, sessionCwd } from '../fsio.js';\nimport { requireBook, parseList, parseFactLines, parseFactEvidence, textBlock, recordBasis } from './common.js';\nimport { parseCognitionLines } from '../cognition.js';\nimport { commitChapter } from '../chapter-commit.js';\nimport { buildBriefing } from '../briefing.js';\nimport { chapterCharTarget, CHAR_MARGIN } from '../audit.js';\n\nexport function defineBriefingTool(ctx, config) {\n    return defineTool({\n        name: 'novel_briefing',\n        description: '写前简报：为第N章组装上下文包（细纲→出场人物卡→账本摘要→未回收伏笔→命中的世界书条目→上一章结尾→原著锚段→前文摘要→全书大纲，按预算裁剪）。锚段是从最近章节挑的味道样本——模仿其语感节奏，勿抄词句；有基线时附文风指纹。写章前必调；模型「看不见前文」的问题由它兜底。回执里的 basis 是本次简报的**依据指纹**（细纲/契约/世界书的内容哈希）：落盘时服务端会重算比对，简报生成后这三样被改过就会告警。',\n        parameters: {\n            book: { type: 'string', required: true, description: '书目名。' },\n            chapter: { type: 'integer', required: true, description: '章号。' },\n            cast: { type: 'string', description: '本章出场人物（逗号分隔）；省略则用工程 cast 全员。' },\n        },\n        output: {\n            schema: {\n                type: 'object',\n                additionalProperties: false,\n                properties: {\n                    book: { type: 'string', required: true },\n                    chapter: { type: 'integer', required: true },\n                    totalChars: { type: 'integer', required: true },\n                    dropped: { type: 'array', items: { type: 'string' }, required: true },\n                    // 截断登记：装进包但被截短的块（硬约束块的截断已同步升进 warnings，\n                    // 这里保留结构化明细供面板/模型对账）。空数组 = 无截断。\n                    truncated: { type: 'array', required: true, items: { type: 'object', additionalProperties: false, properties: {\n                        name: { type: 'string', required: true },\n                        original: { type: 'integer', required: true },\n                        kept: { type: 'integer', required: true },\n                    } } },\n                    // 冲突组裁决记录（同一实体被多块各讲一遍时谁留谁丢）。\n                    // 与 dropped 分开：dropped 是「预算装不下」，这里是「讲法冲突」。\n                    conflicts: { type: 'array', required: true, items: { type: 'object', additionalProperties: false, properties: {\n                        group: { type: 'string', required: true }, winner: { type: 'string', required: true },\n                        loser: { type: 'string', required: true }, reason: { type: 'string', required: true },\n                    } } },\n                    rendered: { type: 'string', required: true },\n                    sections: { type: 'array', required: true, items: { type: 'object', additionalProperties: false, properties: {\n                        name: { type: 'string', required: true }, content: { type: 'string', required: true },\n                    } } },\n                    warnings: { type: 'array', items: { type: 'string' }, required: true },\n                    voiceCount: { type: 'integer' },\n                    contractDigest: { type: 'string' },\n                    hiddenCount: { type: 'integer' },\n                    droppedCast: { type: 'array', items: { type: 'string' } },\n                    // 依据指纹（陈旧检测的锚点）：digest 是本次简报依据的合成哈希，\n                    // sources 是各来源的分项哈希。写章落盘时服务端重算比对。\n                    basis: { type: 'object', required: true, additionalProperties: false, properties: {\n                        digest: { type: 'string', required: true },\n                        version: { type: 'integer', required: true },\n                        sources: { type: 'array', required: true, items: { type: 'object', additionalProperties: false, properties: {\n                            type: { type: 'string', required: true }, hash: { type: 'string', required: true },\n                        } } },\n                    } },\n                },\n            },\n        },\n        isConcurrencySafe: () => true,\n        async execute(args, exec) {\n            const book = assertBookName(args.book);\n            const io = createFsio(ctx, exec, sessionCwd(exec));\n            const { novel } = await requireBook(io, book);\n            const n = args.chapter;\n            if (!Number.isInteger(n) || n < 1) throw new Error('chapter 必须是正整数');\n\n            // 组装只有一个实现（lib/briefing.js）——批量起草走同一份，保护不会漏在批量路径上\n            // 简报的「本章字数目标」段必须与 novel_write_chapter 的门禁**同一口径**：\n            // 描述里写着「以简报为准」，简报报 2000–4000 而门禁按本书档位判 1500–3000，\n            // 模型就会照简报写完再被退稿（本轮要消灭的「两处相反结论」的最坏形态）。\n            const { config: briefCfg } = effectiveCharConfig(config, novel);\n            const brief = await buildBriefing({\n                config: briefCfg, io, book, novel, n,\n                castNames: args.cast !== undefined ? parseList(args.cast) : null,\n            });\n            // 落一份依据指纹（服务端自己的记录）：写章提交时据此核对「简报是否已过期」。\n            // 模型参不参与都能查——靠自觉带回指纹的那条路已经不信了。\n            await recordBasis(io, pathsFor(book), n, brief.basis);\n            return {\n                book, chapter: brief.chapter,\n                sections: brief.sections, totalChars: brief.totalChars, dropped: brief.dropped,\n                truncated: brief.truncated,\n                conflicts: brief.conflicts,\n                rendered: brief.rendered, warnings: brief.warnings,\n                ...(brief.contractDigest === null ? {} : { contractDigest: brief.contractDigest, hiddenCount: brief.hiddenCount }),\n                ...(brief.droppedCast.length === 0 ? {} : { droppedCast: brief.droppedCast }),\n                voiceCount: brief.voiceCount,\n                basis: {\n                    digest: brief.basis.digest,\n                    version: brief.basis.version,\n                    sources: brief.basis.sources,\n                },\n            };\n        },\n        render: (_args, v) => textBlock(\n            `第${v.chapter}章写前简报（${v.totalChars} 字${v.dropped.length > 0 ? `，因预算丢弃：${v.dropped.join('、')}` : ''}${v.conflicts.length > 0 ? `，设定冲突 ${v.conflicts.length} 处已裁决` : ''}）`\n            + (v.contractDigest !== undefined ? `\\n场景契约：${v.contractDigest}${v.hiddenCount > 0 ? `（隐藏 ${v.hiddenCount} 人·档案未注入、正文也不许出现其名）` : ''}` : '')\n            + `\\n\\n${v.rendered}`\n            + (v.warnings.length > 0 ? `\\n\\n⚠ ${v.warnings.join('\\n⚠ ')}` : '')\n        ),\n    });\n}\n\nexport function defineWriteChapterTool(ctx, config, deps = {}) {\n    /** D1 引擎（落盘后自动打标要用）。缺省 null → 跳过自动打标，其余行为不变。 */\n    const engine = deps.engine ?? null;\n    return defineTool({\n        name: 'novel_write_chapter',\n        description: `写整章并落盘（硬约束链）：先 novel_briefing 拿上下文包，再按细纲成稿后调用本工具。**字数标准（网文连载常规）：默认单章 ${config.minChapterChars}–${config.maxChapterChars} 字、目标 ${chapterCharTarget(config)} 字左右**——但**本书的实际区间以 novel_briefing 的「本章字数目标」段为准**（它按「本书自定义区间 > 投放平台口径 > 插件默认」现算，与门禁同源），不足下限直接退稿，字数不够就把细纲场景写细写透、不要注水。**调用前先自查字数**：按本工具字数口径（先剥 markdown 强调标记、再去空白）数一遍正文，确认 ≥简报给的「下限 +${CHAR_MARGIN}」再提交（未自定义时即 ${config.minChapterChars + CHAR_MARGIN}）——模型常把中文字数估短（卡在 1980 这类贴线值），且机审要求留 ${CHAR_MARGIN} 字余量，卡线值会被口径抖动打回；自查能避开反复被机审退稿。门禁：细纲未批准→拒绝；机审不过（字数上下限/与前文高度重复/要素缺失）→拒绝；账本同章改值冲突→拒绝。**引号规范（GB/T 15834—2011）：横排文稿国标引号为弯引号“”‘’——正文一律用弯引号，禁用直角引号「」『』（落盘时自动转换并在 warnings 计数，下笔就写对才不打断语感）。**通过后版本化保存（永不覆盖旧版）+ 落账 + 审计。**节奏铁律：一次只写一章**——本章落盘后立即停下向用户汇报（本章要点 + 下一章建议），由用户决定是否继续，绝不擅自连写下一章。**字数区间怎么定**：用户给了每章字数就用它（锻炉面板「本章字数」或 novel_project action=chars），否则用投放平台口径（${platformLimitsText()}），两者都没给才用上面的默认值；落在区间中段、别贴顶线（超顶线在番茄是完读率杀手，会被直接打回）。`,\n        parameters: {\n            book: { type: 'string', required: true, description: '书目名。' },\n            chapter: { type: 'integer', required: true, description: '章号。' },\n            title: { type: 'string', required: true, description: '本章标题（进文件名，非法字符自动清洗）。' },\n            content: { type: 'string', required: true, description: '本章正文全文（按「落笔即防」规范写干净再交；引号一律用弯引号“”‘’，不用直角引号「」『』）。' },\n            summary: { type: 'string', required: true, description: '本章一句话梗概（进章节索引，供后续写前简报）。' },\n            cast: { type: 'string', description: '本章出场人物（逗号分隔），用于覆盖率检查与账本摘要。' },\n            facts_updates: { type: 'string', description: '本章状态变化，多行「实体|键|值[|备注][|状态]」（如：测试角色|境界|筑基三层）。状态三态 confirmed/unknown/pending：设定还没定的写 unknown 并写明原因（正文不得替它补值），待复核写 pending。账本冲突会拒绝保存。' },\n            facts_evidence: { type: 'string', description: '可选：facts_updates 里每条变化在**本章正文**里的原文证据，多行「实体|键|正文原句」。给了就硬校验——证据必须逐字（忽略空白差异）出现在本次提交的正文里，找不到整章拒绝保存（防「账本记了正文没写的事」）；不给不做校验。一行对应一条 facts_updates。' },\n            cognition_updates: { type: 'string', description: '可选：本章认知变化，多行「谁|知道|信息」或「谁|不知道|信息」（如：张三|不知道|师尊是凶手）。「读者|知道|信息」记读者已知（信息差）。人物**初次得知**某事的那一章必须声明——认知账本会在后续章节的写前简报里守住「谁知道什么」的边界，防「不该知道的人知道了」。' },\n            basis: { type: 'string', description: '本次依据的简报指纹（novel_briefing 回执里的 basis.digest，原样带回来）。带上它，落盘时会核对你用的简报与当前设定是否还一致——不一致会明确告警。不带也能查（服务端有自己留的记录），带上多一道交叉核对。' },\n            force: { type: 'boolean', description: 'true=显式放行未批准细纲 / 内容门禁 / 细纲禁项（记入审计，慎用）。注意：熔断（同章连续驳回≥3次）不由此开关放行，需先 novel_outline approve 重批细纲或 novel_scene save 更新场景契约清零。' },\n        },\n        output: {\n            schema: {\n                type: 'object',\n                additionalProperties: false,\n                properties: {\n                    book: { type: 'string', required: true },\n                    chapter: { type: 'integer', required: true },\n                    path: { type: 'string', required: true },\n                    version: { type: 'integer', required: true },\n                    chars: { type: 'integer', required: true },\n                    forced: { type: 'boolean', required: true },\n                    // 0.20.0（引号规范·GB/T 15834—2011）：本次落盘前自动转换的直角引号数\n                    // （「」『』→“”‘’，栈式配对嵌套交替）。模型可转述给用户；0 = 无需转换。\n                    quoteConverted: { type: 'integer', required: true },\n                    // 进度卡：模型章末汇报的事实由**工具现算**（方向1 汇报走代码强制），\n                    // 模型只转述，不得自数/自抄历史消息里的旧数字。\n                    progress: { type: 'object', required: true, additionalProperties: false, properties: {\n                        chapters: { type: 'integer', required: true },\n                        facts: { type: 'integer', required: true },\n                        openForeshadows: { type: 'integer', required: true },\n                        pendingProposals: { type: 'integer', required: true },\n                        nextChapter: { type: 'integer', required: true },\n                        nextOutlineReady: { type: 'boolean', required: true },\n                        session: { type: 'object', additionalProperties: false, properties: {\n                            chapters: { type: 'integer', required: true },\n                            firstAvg: { type: 'integer', required: true },\n                            // 首稿序列（按章号升序）：面板/模型看的是**趋势**，不是单个均值\n                            firstSeries: { type: 'array', required: true, items: { type: 'object', additionalProperties: false, properties: {\n                                chapter: { type: 'integer', required: true }, chars: { type: 'integer', required: true },\n                            } } },\n                            // 参照＝全书**其它会话**的首稿均值（同口径；0.18.0 前这里是成稿\n                            // 基线，与首稿不同口径 → 门禁越起作用比值越低，第 1 章就误报）\n                            bookFirstAvg: { type: 'integer', required: true },\n                            referenceChapters: { type: 'integer', required: true },\n                            warn: { type: 'string' },\n                            // 疲劳分级：'hard' = 上下文体量判死（继续写大概率 400），'soft' = 质量建议\n                            level: { type: 'string' },\n                            // 上下文体量估算（保守下限：草稿两份 + 每回合简报包；其余回执未计）\n                            contextEst: { type: 'object', additionalProperties: false, properties: {\n                                turns: { type: 'integer', required: true },\n                                draftChars: { type: 'integer', required: true },\n                                estTokens: { type: 'integer', required: true },\n                                budgetTokens: { type: 'integer', required: true },\n                                pct: { type: 'integer', required: true },\n                            } },\n                        } },\n                    } },\n                    addedFacts: { type: 'array', required: true, items: { type: 'object', additionalProperties: false, properties: {\n                        entity: { type: 'string', required: true }, key: { type: 'string', required: true },\n                        value: { type: 'string', required: true }, chapter: { type: 'integer', required: true },\n                        status: { type: 'string', required: true },\n                        note: { type: 'string' },\n                        // 正文证据（facts_evidence 校验通过时随行落账；缺省无此键）\n                        evidence: { type: 'string' },\n                    } } },\n                    addedCognition: { type: 'array', required: true, items: { type: 'object', additionalProperties: false, properties: {\n                        subject: { type: 'string', required: true },\n                        // knows/doesNotKnow（机器值；「读者|知道」也走 knows，subject 区分）\n                        verb: { type: 'string', required: true },\n                        info: { type: 'string', required: true }, chapter: { type: 'integer', required: true },\n                    } } },\n                    // 认知倒退显形（对已知的 info 重申「不知道」——失忆/装傻合法，但必须看见）\n                    cognitionRegressions: { type: 'array', required: true, items: { type: 'string' } },\n                    audit: { type: 'object', required: true, additionalProperties: false, properties: {\n                        chars: { type: 'integer', required: true },\n                        paragraphCount: { type: 'integer', required: true },\n                        avgParagraphChars: { type: 'integer', required: true },\n                        sentenceCount: { type: 'integer', required: true },\n                        dialogueRatio: { type: 'number', required: true },\n                        endingHook: { type: 'object', required: true, additionalProperties: false, properties: {\n                            detected: { type: 'boolean', required: true }, kind: { type: 'string' },\n                        } },\n                        repetition: { type: 'object', required: true, additionalProperties: false, properties: {\n                            chapter: { type: 'integer' }, jaccard: { type: 'number', required: true },\n                        } },\n                        coverage: { type: 'object', required: true, additionalProperties: false, properties: {\n                            terms: { type: 'integer', required: true },\n                            missing: { type: 'array', items: { type: 'string' }, required: true },\n                        } },\n                        latinRuns: { type: 'array', items: { type: 'string' }, required: true },\n                        // 0.19.2（引号规范）：直角引号命中次数（机审判定 quoteStyle 用）\n                        cornerQuotes: { type: 'integer', required: true },\n                    } },\n                    noai: { type: 'object', required: true, additionalProperties: false, properties: {\n                        score: { type: 'integer', required: true }, level: { type: 'string', required: true },\n                        topIssues: { type: 'array', items: { type: 'string' }, required: true },\n                    } },\n                    contentGate: { type: 'object', required: true, additionalProperties: false, properties: {\n                        ok: { type: 'boolean', required: true },\n                        blocking: { type: 'array', items: { type: 'string' }, required: true },\n                        warnings: { type: 'array', items: { type: 'string' }, required: true },\n                    } },\n                    // 质量债（⑦）：本章欠的账。level = 本章最重的一档\n                    // （none/minor/major/hard）——minor 是可以欠着的局部瑕疵，\n                    // major 影响后续结构该停下重规划，hard 是被 force 放行的硬门禁。\n                    qualityDebt: { type: 'object', required: true, additionalProperties: false, properties: {\n                        level: { type: 'string', required: true },\n                        items: { type: 'array', required: true, items: { type: 'object', additionalProperties: false, properties: {\n                            code: { type: 'string', required: true }, level: { type: 'string', required: true },\n                            message: { type: 'string', required: true },\n                        } } },\n                    } },\n                    gate: { type: 'object', additionalProperties: false, properties: {\n                        coverage: { type: 'number', required: true },\n                        drift: { type: 'number' },\n                        missedScenes: { type: 'array', items: { type: 'string' }, required: true },\n                        bannedHits: { type: 'array', items: { type: 'string' }, required: true },\n                        passed: { type: 'boolean', required: true },\n                    } },\n                    warnings: { type: 'array', items: { type: 'string' }, required: true },\n                    reminders: { type: 'array', items: { type: 'string' }, required: true },\n                    // 索引续建实况（落盘后由工具现算，模型只转述）：ok 与降级都必须可见，\n                    // 静默失败会让「回溯用摘录」这条路悄悄断掉，模型退回整章读。\n                    indexNote: { type: 'string', required: true },\n                },\n            },\n        },\n        isConcurrencySafe: () => false,\n        async execute(args, exec) {\n            const book = assertBookName(args.book);\n            const io = createFsio(ctx, exec, sessionCwd(exec));\n            const p = pathsFor(book);\n            const { novel } = await requireBook(io, book);\n            const n = args.chapter;\n            if (!Number.isInteger(n) || n < 1) throw new Error('chapter 必须是正整数');\n            if (typeof args.title !== 'string' || args.title.trim() === '') throw new Error('title 不能为空');\n            if (typeof args.content !== 'string' || args.content.trim() === '') throw new Error('content 不能为空');\n            if (typeof args.summary !== 'string' || args.summary.trim() === '') throw new Error('summary 不能为空（供后续写前简报）');\n\n            // 全部硬约束在 lib/chapter-commit.js —— 与 D2 并发批量起草共用同一条提交链。\n            // 这里只做入参校验，然后交给它（阶段门禁/熔断/机审/账本/内容门禁/契约指标/落盘/审计）。\n            // 字数门禁按本书档位取：自定义区间 > 平台口径 > 插件配置（novel.json 是唯一真相）。\n            // 三档都没设过时 effectiveCharConfig 原样返回同一个 config 引用——默认行为结构性不变。\n            const { config: cfg } = effectiveCharConfig(config, novel);\n            const committed = await commitChapter({\n                config: cfg, io, p, book, novel, n,\n                title: args.title, content: args.content, summary: args.summary,\n                castNames: args.cast !== undefined ? parseList(args.cast) : [],\n                updates: parseFactLines(args.facts_updates),\n                evidences: parseFactEvidence(args.facts_evidence),\n                cognitions: parseCognitionLines(args.cognition_updates),\n                force: args.force === true,\n                basisDigest: typeof args.basis === 'string' && args.basis.trim() !== '' ? args.basis.trim() : null,\n                engine,\n            });\n            return { book, chapter: n, ...committed };\n        },\n        render: (_args, v) => textBlock(\n            `已保存 第${v.chapter}章 v${v.version}（${v.chars} 字）→ ${v.path}${v.forced ? '（⚠ force 放行）' : ''}\\n`\n            + `机审：段 ${v.audit.paragraphCount}·对话占比 ${v.audit.dialogueRatio}·章末钩子 ${v.audit.endingHook.detected ? v.audit.endingHook.kind : '无'}·与前文最大重合 ${v.audit.repetition.jaccard}`\n            + `${v.quoteConverted > 0 ? `·直角引号已转换 ${v.quoteConverted} 处` : '·直角引号 0'}\\n`\n            + `去AI味：${v.noai.level}（${v.noai.score}/100）${v.noai.topIssues.length > 0 ? `\\n  - ${v.noai.topIssues.join('\\n  - ')}` : ''}\\n`\n            + `内容门禁：${v.contentGate.ok ? '通过 ✓' : '⚠ 有阻断项（force 放行）'}\\n`\n            + (v.warnings.length > 0 ? `警告：${v.warnings.join('；')}\\n` : '')\n            + `${v.indexNote}\\n`\n            + `账本落账 ${v.addedFacts.length} 条${v.addedCognition.length > 0 ? `\\n认知落账 ${v.addedCognition.length} 条：${v.addedCognition.map((c) => `${c.subject}${c.verb === 'knows' ? '知道' : '不知道'}「${c.info}」`).join('；')}` : ''}\\n`\n            + `进度卡（本章落盘后现状，据实转述、勿自数）：已写 ${v.progress.chapters} 章 · 账本 ${v.progress.facts} 条 · 伏笔在册 ${v.progress.openForeshadows} 条 · 待批提案 ${v.progress.pendingProposals} 条；下一章 第${v.progress.nextChapter}章${v.progress.nextOutlineReady ? '细纲已就绪' : '细纲待 novel_outline save_chapter'}`\n            + (v.progress.session\n                ? `\\n会话状态：本会话已写 ${v.progress.session.chapters} 章 · 首稿均长 ${v.progress.session.firstAvg} 字`\n                  + `（首稿＝门禁驳回前的初稿字数，不是成稿字数；其它会话首稿均值 ${v.progress.session.bookFirstAvg} 字，参照 ${v.progress.session.referenceChapters} 章）`\n                  + (v.progress.session.warn\n                    ? `\\n⚠ ${v.progress.session.warn}\\n⚠⚠ 会话疲劳已触发——本轮回复必须向用户【显式】建议换新会话：面板疲劳横幅「创建新会话并交接」一键完成（新会话粘贴交接摘要即续写）。不要沉默地继续写下一章。`\n                    : '')\n                : '')\n            + `\\n交付：正文已随本次落盘送达（面板章节列表立即可见），不要再调宿主 present 重复交付。`\n        ),\n    });\n}\n"
