    {
      "path": "lib/server-routes/chapters.js",
      "content": "// lib/server-routes/chapters.js — 章节路由（目录 / 读正文 / 保存 / 一键写章占位 /\n// 一键润色 / 一键机械校对）。\n//\n// 从 server-api.js 按域拆出；每条路由的入口条件、响应体逐字保留。\n// fence 校验已中央收口到 server-api.js 派发层（2026-10-28），路由内不再各自检查。\n// runChapterRevision 是 polish/proofread 共用的实现（原样从 registerServerApi 内搬出）。\n//\n// ⚠️ POST /chapters/:no（面板「💾 保存」）**必须走 lib/chapter-commit.js 那条唯一提交链**：\n// 它曾是全插件唯一的旁路——任意字数（含 0 字）都能落盘并写进 novel.json.chars，\n// 机审/内容门禁/账本/审计全被绕空，「代码强制 > 提示词自觉」在这条路上不成立。\n// 现在面板与模型共用同一套判定，只在**流程门禁**（细纲是否已批准）上分道：\n// 人手工改稿不该被「先写细纲」拦住，但内容级判定（字数/重复/死人复活/泄底）一条不让。\n\nimport { runChapterGates, isGateRejection } from '../chapter-commit.js';\nimport { normalizeQuotes } from '../punctuation.js';\nimport { accumulateDebt } from '../quality-debt.js';\n\n/**\n * 发布前把模型拉进回路（D1 的 REST 面）。\n *\n * 两个端点共用一条实现：polish=按病灶清单整章改写，proofread=机械校对。\n * 三条纪律：\n *   ① 产物一律是**提案**（用户点「应用」才生成新版本）——旁路不能成为绕过提案制的后门；\n *   ② 引擎失败回**人话**（code + message + advice）+ 语义化状态码，不再裸 501；\n *   ③ actor 记 'user'——这是面板按钮触发的，不是模型自己发起的。\n */\nasync function runChapterRevision(req, res, bookId, chapterNo, mode, api) {\n    const { engine, config, writeJson, readJsonBody, fail, locateBook, store, polishIssues, sectionOf, parseBanRules, runRevisionTask, validSessionId, requestSession } = api;\n    // 请求形状校验先于引擎 503（与 draft-batch 同款纪律：4xx 不该被 503 抢答）\n    const body = await readJsonBody(req).catch(() => ({}));\n    if (body.session !== undefined && typeof body.session === 'string' && body.session !== ''\n        && !validSessionId(body.session)) {\n        return fail(res, 400, 'INVALID_FIELD', 'session id 形状不合式');\n    }\n    if (engine === null) {\n        return fail(res, 503, 'ENGINE_UNAVAILABLE', '模型引擎未就绪：本进程没有可用的模型服务');\n    }\n    try {\n        // 会话跟书走：同书多根并存时按 sessions 归属选拷贝（与列表端同判据），\n        // 否则面板书卡显示 A 拷贝、引擎却改到 B 拷贝（2026-10-19 真机实锤）\n        const found = await locateBook(bookId, { session: requestSession(req, body) });\n        if (!found) return fail(res, 404, 'NOT_FOUND', '书不存在');\n        const { fsio } = found;\n        const novel = JSON.parse(found.text);\n        const rec = novel.chapters?.[String(chapterNo)];\n        const recRel = store.chapterRelPath(rec, bookId);\n        if (!recRel) return fail(res, 400, 'NO_CHAPTER', `第${chapterNo}章尚未保存，无可修订内容`);\n        const content = (await fsio.readText(recRel).catch(() => null)) ?? '';\n        if (content.trim() === '') return fail(res, 400, 'EMPTY_CHAPTER', `第${chapterNo}章正文为空`);\n\n        const p = store.pathsFor(bookId);\n        const outline = (await fsio.readText(p.chapterOutline(chapterNo)).catch(() => null)) ?? '';\n        const issues = mode === 'polish'\n            ? polishIssues(content, { top: Math.max(1, config.scanTopK) })\n            : [];\n        const banSection = sectionOf(outline, ['本章禁止偏离项', '禁止偏离']);\n        const forbidden = mode === 'polish' ? parseBanRules(banSection).banned : [];\n\n        const result = await runRevisionTask(engine, fsio, bookId, {\n            mode, chapter: chapterNo, title: rec.title, content, issues, forbidden, actor: 'user',\n            sessionId: typeof body.session === 'string' && body.session !== '' ? body.session : undefined,\n            // 候选链：书的归属会话（创建它的会话 agent 大概率活着、工作区必然对）\n            sessionCandidates: Array.isArray(novel.sessions) ? novel.sessions.filter((s) => typeof s === 'string' && s !== '') : [],\n        });\n\n        if (!result.ok) {\n            const code = result.error?.code ?? 'ENGINE_FAILURE';\n            const status = code === 'ENGINE_UNAVAILABLE' ? 503\n                : code === 'NO_ROUTE' ? 409\n                    : code === 'GUARD_BLOCKED' ? 422\n                        : code === 'ABORTED' ? 499\n                            : 502;\n            return writeJson(res, status, {\n                ok: false,\n                error: { code, message: result.error?.message ?? '引擎调用失败', advice: result.error?.advice ?? '' },\n                value: {\n                    mode, chapter: chapterNo, attempts: result.attempts,\n                    blocked: result.blocked ?? null,\n                    warnings: result.warnings ?? [],\n                },\n            });\n        }\n        return writeJson(res, 200, {\n            ok: true,\n            value: {\n                mode: result.mode, chapter: result.chapter, proposalId: result.proposalId,\n                chars: result.chars, deltaChars: result.deltaChars,\n                attempts: result.attempts,\n                route: result.route === null ? null : { provider: result.route.provider, model: result.route.model, source: result.route.source },\n                warnings: result.warnings,\n                next: `提案 ${result.proposalId} 已登记——到「待批准提案」里点应用才生成新版本`,\n            },\n        });\n    } catch (error) {\n        return fail(res, 500, 'IO_FAILURE', String(error));\n    }\n}\n\n/**\n * @param {object} req 请求\n * @param {object} res 响应\n * @param {string[]} segments 路径段\n * @param {object} api 共享依赖（http 基元 + workspace 索引 + 库）\n * @returns {Promise<boolean>} 是否已处理\n */\nexport async function handle(req, res, segments, api) {\n    const {\n        writeJson, readJsonBody, fail, safeDecode, validBookId, locateBook, parseQuery, requestSession,\n        store, config, versioning, updateJson, isVersionConflict, auditLine,\n    } = api;\n\n    // GET /projects/:id/chapters — 章节目录（听书 / 列表用）\n    if (req.method === 'GET' && segments[0] === 'projects' && segments[2] === 'chapters' && segments.length === 3) {\n        const bookId = safeDecode(segments[1]);\n        if (!validBookId(bookId)) { fail(res, 400, 'BAD_BOOK', 'invalid book id'); return true; }\n        try {\n            // ?session= 归属判据与列表端一致：多根同名书时定位到本会话名下的那份\n            const session = requestSession(req);\n            const found = await locateBook(bookId, { session });\n            if (!found) { fail(res, 404, 'NOT_FOUND', '书不存在'); return true; }\n            const { text } = found;\n            const novel = JSON.parse(text);\n            const list = Object.entries(novel.chapters ?? {})\n                .map(([no, rec]) => ({\n                    no: Number(no),\n                    title: rec?.title ?? `第 ${no} 章`,\n                    chars: rec?.chars ?? 0,\n                    version: rec?.version ?? 0,\n                }))\n                .sort((a, b) => a.no - b.no);\n            writeJson(res, 200, { ok: true, value: list });\n        } catch (error) {\n            fail(res, 500, 'IO_FAILURE', String(error));\n        }\n        return true;\n    }\n\n    // GET /projects/:id/chapters/:no — 读章节正文\n    if (req.method === 'GET' && segments[0] === 'projects' && segments[2] === 'chapters' && segments.length === 4) {\n        const bookId = safeDecode(segments[1]);\n        if (!validBookId(bookId)) { fail(res, 400, 'BAD_BOOK', 'invalid book id'); return true; }\n        const chapterNo = Number(segments[3]);\n        // 与 POST 同款守卫：NaN 当键查恒返回空串，看着像「这章没内容」，\n        // 而真相是请求写错了——响亮 400 比静默空值好。\n        if (!Number.isInteger(chapterNo) || chapterNo < 1) { fail(res, 400, 'BAD_CHAPTER', '章节号必须为正整数'); return true; }\n        try {\n            const session = requestSession(req);\n            const found = await locateBook(bookId, { session });\n            if (!found) { fail(res, 404, 'NOT_FOUND', '书不存在'); return true; }\n            const { fsio, text } = found;\n            const novel = JSON.parse(text);\n            const rec = novel.chapters?.[String(chapterNo)];\n            // 章节记录 schema 只认 path / files[].file（都含书目前缀）——\n            // 0.13.1 曾读不存在的 rec.file 还另拼一层 bookId/正文/ → 阅读器恒空。\n            const rel = store.chapterRelPath(rec, bookId);\n            if (!rel) { writeJson(res, 200, { ok: true, value: '' }); return true; }\n            const content = await fsio.readText(rel).catch(() => '');\n            writeJson(res, 200, { ok: true, value: content ?? '' });\n        } catch (error) {\n            fail(res, 500, 'IO_FAILURE', String(error));\n        }\n        return true;\n    }\n\n    // POST /projects/:id/chapters/:no — 保存章节（面板「💾 保存」）\n    // 判定段与 novel_write_chapter **共用同一个函数**（runChapterGates：机审/账本/内容门禁/\n    // 禁项/熔断，只豁免流程门禁）；写段留在这里——版本号必须在 updateJson 的冲突重放里算，\n    // 两个面板同时存同一章不能撞车（commitChapter 的写段没有这个重放，不能直接借用）。\n    // 被门禁拦下 → 409 + 原文，面板给「仍要保存（记审计）」的二次确认。\n    if (req.method === 'POST' && segments[0] === 'projects' && segments[2] === 'chapters' && segments.length === 4) {\n        const bookId = safeDecode(segments[1]);\n        if (!validBookId(bookId)) { fail(res, 400, 'BAD_BOOK', 'invalid book id'); return true; }\n        const chapterNo = Number(segments[3]);\n        if (!Number.isInteger(chapterNo) || chapterNo < 1) { fail(res, 400, 'BAD_CHAPTER', '章节号必须为正整数'); return true; }\n        let body;\n        try {\n            body = await readJsonBody(req);\n        } catch (error) {\n            fail(res, 400, 'BAD_BODY', `请求体不是合法 JSON：${String(error?.message ?? error)}`);\n            return true;\n        }\n        const rawContent = String(body.text ?? '');\n        if (rawContent.trim() === '') {\n            // 旧实现在这里连校验都没有：编辑器空稿一存 → 0 字章节落盘 + 索引登记 + 版本 +1\n            fail(res, 400, 'EMPTY_CHAPTER', '正文为空——面板保存不写空版本（要清掉这一章请走删除/提案）');\n            return true;\n        }\n        // 引号规范（GB/T 15834—2011）：面板人工保存与写章链同一道闸。判定段内部\n        // 也会再转一次（幂等），这里先转是为了落盘/冲突比较/响应回显用同一份文本；\n        // 转换数经 judged.softWarnings 可见，不静默。\n        const content = normalizeQuotes(rawContent).text;\n        try {\n            // 保存跟读同源：body.session（客户端 saveChapter 会带上）归属判据选拷贝\n            const found = await locateBook(bookId, { session: requestSession(req, body) });\n            if (!found) { fail(res, 404, 'NOT_FOUND', '书不存在'); return true; }\n            const { fsio, text } = found;\n            const novel = JSON.parse(text);\n            store.migrateNovel(novel);   // 旧书借这次写盘补上 schemaVersion 与结构锚点\n            const prev = novel.chapters?.[String(chapterNo)];\n            // 标题：旧实现一律写「第 N 章」，面板每存一次就把真标题抹掉一次\n            // （chapterRecord 的 title 无兜底，旧值直接丢）。人工保存没给标题就沿用原标题。\n            const given = typeof body.title === 'string' ? body.title.trim() : '';\n            const placeholder = given === '' || given === `第 ${chapterNo} 章`;\n            const title = placeholder ? (prev?.title ?? `第 ${chapterNo} 章`) : given;\n            const force = body.force === true;\n            // 判定段（不过就 throw，由下面的 isGateRejection 分 409/500）\n            // 字数口径与工具面同源：本书自定义区间 > 平台 > 插件默认。面板保存和模型写章\n            // 走的是同一个 runChapterGates，配置不同源就会「同样一版字，人存得进、机器拒」。\n            const judged = await runChapterGates({\n                config: store.effectiveCharConfig(config, novel).config,\n                io: fsio, p: store.pathsFor(bookId), book: bookId, novel, n: chapterNo,\n                content, castNames: [], updates: [], force, committedBy: 'user', stageGate: false,\n                // 人工保存不驱动熔断也不受其锁死（skipBreaker）：熔断解锁条件（聊天里\n                // approve 细纲）对人工编辑不可达也无意义；模型/批量路径不带此参，行为不变。\n                skipBreaker: true,\n            });\n            // 读时捕获版本 + 冲突重放：版本号（prev.latest + 1）必须从**重读后的\n            // 最新索引**推出来。原实现是「先读一次 → 末尾 writeTextIfVersion」，\n            // 而那是写前一刻才 stat，版本永远匹配 —— 读-改-写窗口里别人刚落的\n            // 新版本会被抹掉，还会算出同一个 vN 覆盖别人的正文文件。\n            let rec;\n            await updateJson(fsio, `${bookId}/novel.json`, async (latest) => {\n                if (latest === undefined) throw new Error(`书目不存在：${bookId}`);\n                store.migrateNovel(latest);\n                const prevLatest = latest.chapters?.[String(chapterNo)];\n                // 版本号统一走 versioning.nextVersion（唯一入口，见 lib/versioning.js 的约定）：\n                // 这里原本内联「latest + 1」，是第三个绕过统一入口的地方。索引里的 latest 一旦\n                // 缺失或破损（手工编辑过 novel.json、repair 之前的旧索引），而磁盘上其实已有 v1，\n                // 就会算出同一个 v1 → writeText 以 create 撞车 → 用户看到 500 IO_FAILURE，\n                // 而真相只是版本号算重了。按磁盘上的真实文件名取最大版本号才是唯一真相。\n                const names = (prevLatest?.files ?? []).map((f) => f.file.split('/').pop() ?? '');\n                const version = versioning.nextVersion(names, chapterNo);\n                const rel = `${bookId}/正文/${versioning.chapterFileName(chapterNo, title, version)}`;\n                try {\n                    await fsio.writeText(rel, `${content.trimEnd()}\\n`, 'create');    // 永不覆盖已有版本\n                } catch (error) {\n                    // 撞上自己上一轮重放写的那一份（逐字相同）→ 认领；否则是别人的版本\n                    if (!isVersionConflict(error) || (await fsio.readText(rel)) !== `${content.trimEnd()}\\n`) throw error;\n                }\n                rec = store.chapterRecord(prevLatest, {\n                    title, version, file: rel,\n                    // 字数口径与机审同源（先剥 markdown 强调再数）——旧实现直接数原文，\n                    // 真机一章 188 个 `*` 被算成 188 字，面板显示的篇幅比读者看到的虚高。\n                    chars: judged.auditResult.chars,\n                });\n                if (!latest.chapters) latest.chapters = {};\n                latest.chapters[String(chapterNo)] = rec;\n                // 跨章节奏状态（②）：面板人工保存也占一章的节奏额度——人改的稿\n                // 照样进冷却矩阵与档位统计，否则面板存的几章在节奏体检里是隐形的\n                // （模型面算得到、面板面算不到，同一本书两套节奏账）。\n                const paceRec = judged.pacing?.record;\n                if (paceRec !== undefined && paceRec !== null) {\n                    if (!latest.pacing || typeof latest.pacing !== 'object') latest.pacing = {};\n                    if (!latest.pacing.chapters || typeof latest.pacing.chapters !== 'object') latest.pacing.chapters = {};\n                    latest.pacing.chapters[String(chapterNo)] = paceRec;\n                }\n                // 面板保存与写章链同源：有债记账，没债清旧账。否则人工重写干净后，\n                // novel_quality 仍会显示上一版的债。\n                // 「怎么覆盖」不在这重写——与 commitChapter 共用 quality-debt.accumulateDebt\n                // 那一份实现（两处各写一遍，清零语义就会在某一次改动里丢掉）。\n                latest.quality = {\n                    ...(latest.quality ?? {}),\n                    debts: accumulateDebt(latest.quality?.debts, chapterNo, judged.debts ?? []),\n                };\n                return { value: latest };\n            });\n            // 审计断档修复（H5）：面板改的每一版正文也要在审计链上可查。\n            // forced/blocked 必须进审计：面板上「仍要保存」放行了什么硬伤，事后要查得到。\n            await fsio.appendLine(`${bookId}/.novel/audit.jsonl`,\n                auditLine('rest/chapter_save', {\n                    chapter: chapterNo, version: rec.latest, title, chars: rec.chars,\n                    forced: force, blocked: judged.cgate.ok ? [] : judged.cgate.blocking.map((b) => b.code),\n                }, 'user'));\n            writeJson(res, 200, {\n                ok: true,\n                value: {\n                    chapter: rec, text: content, chars: rec.chars, version: rec.latest, forced: force,\n                    warnings: [\n                        ...judged.verdict.warnings,\n                        ...judged.cgate.warnings.map((w) => w.message),\n                        ...judged.softWarnings,\n                        ...(judged.cgate.ok ? [] : judged.cgate.blocking.map((b) => `已跳过内容门禁：${b.message}`)),\n                    ],\n                    // force 真的放行了内容门禁时，把被放行的硬伤原样带回——不许静默\n                    ...(judged.cgate.ok ? {} : { blocked: judged.cgate.blocking.map((b) => b.message) }),\n                },\n            });\n        } catch (error) {\n            if (isGateRejection(error)) {\n                // 409＝内容/流程判定没过（用户可改稿或显式 force）；500＝io/程序故障。\n                // 混成一个码，面板就只能把\"正文 1450 字低于下限\"显示成\"服务故障\"。\n                fail(res, 409, 'GATE_REJECTED', String(error?.message ?? error));\n                return true;\n            }\n            fail(res, 500, 'IO_FAILURE', String(error));\n        }\n        return true;\n    }\n\n    // POST /projects/:id/chapters/:no/write — 一键写章（调用 briefing + write_chapter 工具逻辑）\n    if (req.method === 'POST' && segments[0] === 'projects' && segments[2] === 'chapters' && segments[4] === 'write' && segments.length === 5) {\n        // 写章需要模型参与，从 HTTP 端无法直接调用\n        // 返回 501 提示用户通过聊天调用 novel_write_chapter\n        fail(res, 501, 'NOT_IMPLEMENTED', '一键写章需要模型参与，请在聊天中调用 novel_write_chapter');\n        return true;\n    }\n\n    // POST /projects/:id/chapters/:no/polish — 一键润色（D1 旁路引擎：出提案，不落正文）\n    if (req.method === 'POST' && segments[0] === 'projects' && segments[2] === 'chapters' && segments[4] === 'polish' && segments.length === 5) {\n        const bookId = safeDecode(segments[1]);\n        if (!validBookId(bookId)) { fail(res, 400, 'BAD_BOOK', 'invalid book id'); return true; }\n        // runChapterRevision 经 writeJson/fail 收口（两者返回 undefined）——dispatch 契约是\n        // 「本分支已处理必须回 true」，直接 return 它的 undefined 会落到 404 二次写响应\n        // （ERR_HTTP_HEADERS_SENT，真机症状是润色/校对面板只收到半截错）。\n        await runChapterRevision(req, res, bookId, Number(segments[3]), 'polish', api);\n        return true;\n    }\n\n    // POST /projects/:id/chapters/:no/proofread — 一键机械校对（D1 旁路引擎：守卫更严）\n    if (req.method === 'POST' && segments[0] === 'projects' && segments[2] === 'chapters' && segments[4] === 'proofread' && segments.length === 5) {\n        const bookId = safeDecode(segments[1]);\n        if (!validBookId(bookId)) { fail(res, 400, 'BAD_BOOK', 'invalid book id'); return true; }\n        await runChapterRevision(req, res, bookId, Number(segments[3]), 'proofread', api);\n        return true;\n    }\n\n    return false;\n}\n"
    },
    {
      "path": "lib/tools/propose-tools.js",
      "content": "// lib/tools/propose-tools.js — novel_propose：修改提案制（propose / list）。\n//\n// 门禁设计（第一批融合 · A1）：**工具面只有 propose 与 list**。\n//   · 模型能做的：提提案、看提案列表；\n//   · 模型**不能**做的：apply（应用）/ discard（丢弃）/ prune（清理）。\n// apply 一类是用户主权动作，只从 REST 端点（锻炉面板按钮）进入——\n// 见 lib/proposals.js 与 lib/server-api.js 的 /proposals 路由。\n//\n// 于是「模型无法自己批准自己的提案」成为**工具层保证**，不再依赖 persona 自觉：\n// 想改已存章节，模型只能出提案，用户点「应用」才生成新版本。\n\nimport { defineTool } from './define-tool.js';\nimport { assertBookName, createFsio, sessionCwd } from '../fsio.js';\nimport { requireBook, textBlock } from './common.js';\nimport { proposeRevision, listProposals } from '../proposals.js';\n\nexport function defineProposeTool(ctx, config) {\n    return defineTool({\n        name: 'novel_propose',\n        description: '修改提案制：propose 对已存章节提交修订稿（生成提案 id，**不改正文**）；list 列出提案（含每条基于哪一版、本章现在到哪一版）。**通道边界**：想自己动手改稿就直接用 novel_write_chapter（同章追加新版本，旧版永不覆盖——机审驳回后的重写也走它）；本工具是「把修订登记下来、等用户批准」的那条路。apply（应用）与 discard（丢弃）是**用户主权动作**，工具面不提供：提完提案请明确告知用户「到锻炉面板点应用」，不要声称提案已生效。同一章已有 pending 提案时不要重复提新的——先在面板应用或丢弃。',\n        parameters: {\n            action: { type: 'string', required: true, enum: ['propose', 'list'], description: 'propose 提交修订提案；list 列出已有提案。apply/discard/prune 由用户在面板操作，工具面不提供。' },\n            book: { type: 'string', required: true, description: '书目名。' },\n            chapter: { type: 'integer', description: 'propose 必填：要修订的章号。' },\n            content: { type: 'string', description: 'propose 必填：修订后的整章正文（引号一律用弯引号“”‘’，不用直角引号「」『』——登记与应用时自动转换）。' },\n            reason: { type: 'string', description: 'propose：修订原因（进入审计）。' },\n        },\n        output: {\n            schema: {\n                type: 'object',\n                additionalProperties: false,\n                properties: {\n                    book: { type: 'string', required: true },\n                    action: { type: 'string', required: true },\n                    id: { type: 'string' },\n                    chapter: { type: 'integer' },\n                    status: { type: 'string' },\n                    // 基线（T1）：提案基于本章哪一版生成的。schema 是 integer，\n                    // 所以 null/undefined 一律不进响应（见 lib/proposals.js 的携带条件）。\n                    baseVersion: { type: 'integer' },\n                    proposals: { type: 'array', items: { type: 'object', additionalProperties: false, properties: {\n                        id: { type: 'string', required: true }, chapter: { type: 'integer', required: true },\n                        status: { type: 'string', required: true }, createdAt: { type: 'string', required: true },\n                        title: { type: 'string' }, missing: { type: 'boolean' },\n                        reason: { type: 'string' }, preview: { type: 'string' },\n                        // 这条提案基于 v(baseVersion)，而本章现在是 v(latestVersion)——\n                        // 两个数一起给，面板与模型都能自己看出「这条已经陈旧」。\n                        baseVersion: { type: 'integer' }, latestVersion: { type: 'integer' },\n                    } } },\n                },\n            },\n        },\n        isConcurrencySafe: () => false,\n        async execute(args, exec) {\n            const book = assertBookName(args.book);\n            const io = createFsio(ctx, exec, sessionCwd(exec));\n            // requireBook 负责「书存在」校验 + 会话归属补录（面板按会话列书靠它）。\n            await requireBook(io, book);\n\n            if (args.action === 'list') return listProposals(io, book);\n            return proposeRevision(io, book, args, config);\n        },\n        render: (_args, v) => textBlock(\n            v.action === 'propose'\n                ? `提案已登记：${v.id}（第${v.chapter}章，pending）——**尚未改动正文**。请到「锻炉」面板点「应用」才会生成新版本；应用后的新版本同样自动送达，无需调用宿主 present。`\n                : `提案 ${v.proposals.length} 条：${v.proposals.map((x) => `${x.id}(${x.status})`).join('、') || '无'}`\n        ),\n    });\n}\n"
    },
    {
      "path": "lib/server-routes/proposals.js",
      "content": "// lib/server-routes/proposals.js — 提案端点（融合第一批 · A1）。\n//\n// 从 server-api.js 按域拆出；每条路由的入口条件、响应体逐字保留。\n// fence 校验已中央收口到 server-api.js 派发层（2026-10-28），路由内不再各自检查。\n//\n// 提案的「应用 / 丢弃 / 清理」是**用户主权动作**，刻意不进工具面\n// （见 lib/tools/propose-tools.js 的 enum 只有 propose/list）。\n// 面板通过这几个端点操作，审计里 actor 一律记 'user' ——\n// 于是「谁批准的修订」在 audit.jsonl 里可查，模型无法自己批准自己。\n\n/**\n * @param {object} req 请求\n * @param {object} res 响应\n * @param {string[]} segments 路径段\n * @param {object} api 共享依赖（http 基元 + workspace 索引 + 库）\n * @returns {Promise<boolean>} 是否已处理\n */\nexport async function handle(req, res, segments, api) {\n    const { writeJson, fail, safeDecode, validBookId, locateBook, proposals, requestSession } = api;\n\n    // GET /projects/:id/proposals — 列出提案\n    if (req.method === 'GET' && segments[0] === 'projects' && segments[2] === 'proposals' && segments.length === 3) {\n        const bookId = safeDecode(segments[1]);\n        if (!validBookId(bookId)) { fail(res, 400, 'BAD_BOOK', 'invalid book id'); return true; }\n        try {\n            const found = await locateBook(bookId, { session: requestSession(req) });\n            if (!found) { fail(res, 404, 'NOT_FOUND', '书不存在'); return true; }\n            const value = await proposals.listProposals(found.fsio, bookId);\n            writeJson(res, 200, { ok: true, value });\n        } catch (error) {\n            fail(res, 500, 'IO_FAILURE', String(error));\n        }\n        return true;\n    }\n\n    // GET /projects/:id/proposals/:pid — 单条提案全文（应用前让人看清改了什么）\n    if (req.method === 'GET' && segments[0] === 'projects' && segments[2] === 'proposals' && segments.length === 4) {\n        const bookId = safeDecode(segments[1]);\n        if (!validBookId(bookId)) { fail(res, 400, 'BAD_BOOK', 'invalid book id'); return true; }\n        try {\n            const found = await locateBook(bookId, { session: requestSession(req) });\n            if (!found) { fail(res, 404, 'NOT_FOUND', '书不存在'); return true; }\n            const value = await proposals.readProposal(found.fsio, bookId, safeDecode(segments[3]));\n            writeJson(res, 200, { ok: true, value });\n        } catch (error) {\n            fail(res, 404, 'PROPOSAL_NOT_FOUND', String(error?.message ?? error));\n        }\n        return true;\n    }\n\n    // POST /projects/:id/proposals/prune — 清理已终态提案索引\n    if (req.method === 'POST' && segments[0] === 'projects' && segments[2] === 'proposals' && segments[3] === 'prune' && segments.length === 4) {\n        const bookId = safeDecode(segments[1]);\n        if (!validBookId(bookId)) { fail(res, 400, 'BAD_BOOK', 'invalid book id'); return true; }\n        try {\n            const found = await locateBook(bookId, { session: requestSession(req) });\n            if (!found) { fail(res, 404, 'NOT_FOUND', '书不存在'); return true; }\n            const value = await proposals.pruneProposals(found.fsio, bookId, 'user');\n            writeJson(res, 200, { ok: true, value });\n        } catch (error) {\n            fail(res, 400, 'PROPOSAL_REJECTED', String(error?.message ?? error));\n        }\n        return true;\n    }\n\n    // POST /projects/:id/proposals/:pid/apply — 应用提案（生成新版本，旧版保留）\n    if (req.method === 'POST' && segments[0] === 'projects' && segments[2] === 'proposals' && segments[4] === 'apply' && segments.length === 5) {\n        const bookId = safeDecode(segments[1]);\n        if (!validBookId(bookId)) { fail(res, 400, 'BAD_BOOK', 'invalid book id'); return true; }\n        const proposalId = safeDecode(segments[3]);\n        try {\n            const found = await locateBook(bookId, { session: requestSession(req) });\n            if (!found) { fail(res, 404, 'NOT_FOUND', '书不存在'); return true; }\n            const value = await proposals.applyProposal(found.fsio, bookId, proposalId, api.config, 'user');\n            writeJson(res, 200, { ok: true, value });\n        } catch (error) {\n            // 提案不存在 / 状态非 pending / 文件缺失 都是业务性拒绝，不是服务故障。\n            fail(res, 400, 'PROPOSAL_REJECTED', String(error?.message ?? error));\n        }\n        return true;\n    }\n\n    // POST /projects/:id/proposals/:pid/discard — 丢弃提案（正文不动）\n    if (req.method === 'POST' && segments[0] === 'projects' && segments[2] === 'proposals' && segments[4] === 'discard' && segments.length === 5) {\n        const bookId = safeDecode(segments[1]);\n        if (!validBookId(bookId)) { fail(res, 400, 'BAD_BOOK', 'invalid book id'); return true; }\n        const proposalId = safeDecode(segments[3]);\n        try {\n            const found = await locateBook(bookId, { session: requestSession(req) });\n            if (!found) { fail(res, 404, 'NOT_FOUND', '书不存在'); return true; }\n            const value = await proposals.discardProposal(found.fsio, bookId, proposalId, 'user');\n            writeJson(res, 200, { ok: true, value });\n        } catch (error) {\n            fail(res, 400, 'PROPOSAL_REJECTED', String(error?.message ?? error));\n        }\n        return true;\n    }\n\n    return false;\n}"
    },
    {
      "path": "lib/batch-draft.js",
      "content": "// lib/batch-draft.js — D2 · 并发批量起草。\n//\n// 目标：一次把 N 章草稿推出来，但**不牺牲任何一条硬约束**。\n//\n// 四个硬约束（每一条都对应一类真实事故）：\n//   ① **并发生成、串行提交**。章节文件按章号命名、互不覆盖，可以并行写；但账本\n//      （facts/伏笔/novel.json）并发写同一章会互相覆盖 —— 所以生成阶段并发，提交阶段排队。\n//   ② **上下文预算 ×N**。N 章并发 = N 份上下文包同时在场。默认并发 1（保守），上限 4，\n//      且**只在场景契约（B3）裁过上下文的书上放开** —— 第三批的收益在这里兑现。\n//   ③ **顺序依赖是真实的**。并发起草的第 2+ 章看不到前一章的正文（它还没写出来），\n//      所以细纲必须自带衔接信息；「连环悬念」的章节不要并行。\n//   ④ **失败不整批回滚**。N 章里 1 章挂了，其余照落盘 —— 整批回滚等于把好章节扔了重跑。\n//\n// 提交链复用 lib/chapter-commit.js（与单章写**同一条**），所以机审/内容门禁/账本冲突/\n// 悬念保护在批量路径上一个都不会漏。\n\nimport { contractFor } from './scene-contract.js';\nimport { buildBriefing } from './briefing.js';\nimport { commitChapter } from './chapter-commit.js';\nimport { extractChapterText } from './engine-tasks.js';\nimport { chapterCharTarget, paragraphSpecRange } from './audit.js';\nimport { effectiveCharConfig, charConfigSourceLabel } from './store.js';\nimport { isVersionConflict } from './fsio.js';\nimport { recordBasis } from './tools/common.js';\n\n/** 并发上限。再高收益递减、上下文成本线性上升、限流概率陡增。 */\nexport const MAX_CONCURRENCY = 4;\n\n/** 起草系统提示（纯函数）。注意第 5 条——并发场景下模型看不到前一章正文，衔接只能靠细纲。\n *  字数目标此处**现算**（chapterCharTarget），不再写死「2000–4000 / 3000」：\n *  写死的数字一旦与配置漂移，批量路径就成了唯一说错话的地方。 */\nexport function draftSystem(config) {\n    const target = chapterCharTarget(config);\n    // 段落规格的算式只有一份（lib/audit.js）——简报、驳回文案、起草系统提示词共用，\n    // 抄第二份就一定会在某次改口径时只改一处。\n    const spec = paragraphSpecRange(config);\n    return [\n        '你是中文长篇小说的写手。按给定的写前简报与细纲，写出这一章的完整正文。',\n        '硬要求：',\n        '1. 只输出本章正文，不要任何解释、前言、结语、Markdown 代码围栏；',\n        '2. 首行是章节标题（与细纲给的一致）；',\n        '3. **严格按细纲的场景与顺序写**，细纲里的必写场景一个都不能少；',\n        '4. 细纲「本章禁止偏离项」里禁止的内容绝对不许出现（尤其**隐藏人物不许露面、不许被提及**）；',\n        '5. 本章可能与相邻章并行写作，你**看不到前后章正文**——衔接信息只以细纲与简报为准，不要臆造上一章结尾的细节；',\n        '6. 对话要符合人物的语言基因卡（口头禅/绝不说的话/小动作），不要千人一腔；',\n        '7. 情绪用动作/环境/留白暗示，不直写结论句；避免「不禁」「仿佛」「嘴角勾起一抹弧度」这类AI腔；叙述句优先用环境、动作或具体物件起头，不要每句都从主角的感受出发，不要连续用「他看见／他听见／他感到」推进，也不要单独用一整段写内心感受；',\n        '8. 长短句交错；章末留钩子，但不要用新悬念去掩盖旧欠账；',\n        `9. **单章正文 ${config.minChapterChars}–${config.maxChapterChars} 字、目标 ${target} 字左右**（正常网文连载单章篇幅）：不足就把细纲场景写细写透，不要注水凑字；快到 ${config.maxChapterChars} 字就收在钩子处收章——低于下限的稿子会被机审直接退掉。`,\n        `10. **不要一句一段**：单段写足 ${Math.max(1, spec.min)}–${spec.max} 字（约 3–8 句），全章约 ${Math.round(target / spec.max)}–${Math.round(target / (spec.max / 2))} 段。短句单独成段 + 每句后空行，会让全章字数天然停在 1000 出头、怎么改都过不了下限。`,\n    ].join('\\n');\n}\n\n/** 起草提示词（纯函数）。 */\nexport function buildDraftPrompt({ chapter, briefing, chapterOutline }) {\n    return [\n        `【第 ${chapter} 章 · 写前简报】`,\n        String(briefing ?? ''),\n        '',\n        '【本章细纲】',\n        String(chapterOutline ?? ''),\n        '',\n        '请写出这一章的完整正文。',\n    ].join('\\n');\n}\n\n/**\n * 从细纲里推标题与梗概（草稿提交需要，模型不负责起名）。\n * 标题优先取细纲里的 `# 第N章 XXX` / `第N章 XXX`；梗概取第一段正文内容。\n */\nexport function deriveTitleSummary(outlineText, chapter) {\n    const lines = String(outlineText ?? '').split('\\n').map((l) => l.trim());\n    let title = `第 ${chapter} 章`;\n    let summary = '';\n    for (const line of lines) {\n        if (line === '') continue;\n        const heading = line.match(/^#{1,6}\\s*(.+)$/);\n        const plain = heading !== null ? heading[1].trim() : line;\n        if (/^第\\s*[0-9一二三四五六七八九十百零]+\\s*[章回]/.test(plain)) {\n            title = plain.replace(/^#+\\s*/, '').slice(0, 40);\n            continue;\n        }\n        if (summary === '') summary = plain.replace(/^[-*+]\\s*/, '').slice(0, 60);\n    }\n    if (summary === '') summary = `${title}（细纲未提供梗概）`;\n    return { title, summary };\n}\n\n/**\n * 计划一次批量起草（纯函数，可单测）：哪些章能写、哪些被拦、为什么。\n *\n * @param novel             novel.json\n * @param from              起始章号\n * @param count             章数\n * @param availableOutlines 有细纲文件的章号\n * @param approvedOutlines  已在 novel.json 里被批准的章号（缺省 force 时为空）\n * @param force             显式放行未批准细纲（熔断由解除通道清零，不由此放行）\n */\nexport function planDraftBatch({ novel, from, count, availableOutlines = [], approvedOutlines = [], force = false }) {\n    const items = [];\n    const warnings = [];\n    const approved = new Set(approvedOutlines);\n    const available = new Set(availableOutlines);\n    const failures = novel.gateFailures ?? {};\n\n    for (let n = from; n < from + count; n += 1) {\n        const written = novel.chapters?.[String(n)]?.path !== undefined;\n        const tripped = (failures[String(n)] ?? 0) >= 3;\n        let reason = null;\n        if (written) reason = `第${n}章已有正文——修订请走提案（novel_propose），批量起草只写新章`;\n        else if (!available.has(n)) reason = `第${n}章细纲不存在——先 novel_outline save_chapter`;\n        else if (!force && !approved.has(n)) reason = `第${n}章细纲未批准——先 novel_outline approve（确要跳过用 force）`;\n        else if (tripped) reason = `第${n}章熔断中（连续驳回 ${failures[String(n)]} 次）——先改细纲或场景契约（novel_outline approve / novel_scene save），改完计数自动清零`;\n        items.push(reason === null\n            ? { chapter: n, blocked: false, reason: null }\n            : { chapter: n, blocked: true, reason });\n    }\n\n    // 章号连续性：中间缺一章，后面那章的上下文（上一章结尾）就是错的\n    const ready = items.filter((i) => !i.blocked).map((i) => i.chapter);\n    for (let i = 1; i < ready.length; i += 1) {\n        if (ready[i] !== ready[i - 1] + 1) {\n            warnings.push(`可写章号不连续（${ready[i - 1]} → ${ready[i]}）：跳过的那章没有正文，后一章的「上一章结尾」会是空的，衔接只能靠细纲`);\n        }\n    }\n    if (items.every((i) => i.blocked) && items.length > 0) {\n        warnings.push('没有任何一章可以起草——看下面每章的拦截原因');\n    }\n    return { items, ready, blocked: items.filter((i) => i.blocked), warnings };\n}\n\n/**\n * 并发映射，**保序返回**。错误不中断整批：fn 抛错（含同步抛）由本函数捕获，以 Error 实例\n * 占位收进 results——不 reject、不吞项。旧实现裸 await fn，靠调用方自带 try/catch 兜底；\n * 这是导出函数，未来别处裸调一个同步抛错的 fn 就炸整批（真机导入书监控审查结论 P0-1）。\n * @param limit 并发上限（>=1）\n */\nexport async function mapWithConcurrency(items, limit, fn, { signal = null } = {}) {\n    const size = Math.max(1, Math.min(limit, items.length === 0 ? 1 : items.length));\n    const results = new Array(items.length);\n    let cursor = 0;\n    const worker = async () => {\n        for (;;) {\n            if (signal?.aborted === true) return;\n            const index = cursor;\n            cursor += 1;\n            if (index >= items.length) return;\n            try {\n                results[index] = await fn(items[index], index);\n            } catch (err) {\n                results[index] = err instanceof Error ? err : new Error(String(err));\n            }\n        }\n    };\n    await Promise.all(Array.from({ length: size }, worker));\n    return results;\n}\n\n/**\n * 跑一次批量起草：计划 → 并发生成 → 串行提交。\n *\n * 生成失败或提交被门禁拦下都只影响那一章（`ok:false` + 原因），其余照落。\n * @returns {{items, results, concurrency, warnings, stats}}\n */\nexport async function runDraftBatch({\n    engine, config, io, p, book, novel, from, count,\n    concurrency = 1, force = false, onEvent = null, signal = null, sessionId, sessionCandidates,\n}) {\n    const warnings = [];\n    // 字数口径按本书档位现算（自定义 > 平台 > 插件默认）——批量起草与工具面写章、写前简报\n    // 必须同一份 config，否则 D2 落盘的章会绕过用户给这本书设的区间（真机「先写后删」的\n    // 批量版：D2 按默认 4000 上限放行，回头 novel_audit 按本书口径判超长）。\n    const { config: bookConfig, source: charSource } = effectiveCharConfig(config, novel);\n    if (charSource !== 'config') {\n        warnings.push(`本章字数区间 ${bookConfig.minChapterChars}–${bookConfig.maxChapterChars}（出处：${charConfigSourceLabel(charSource, novel)}）`);\n    }\n    const availableOutlines = [];\n    for (let n = from; n < from + count; n += 1) {\n        if ((await io.readText(p.chapterOutline(n))) !== null) availableOutlines.push(n);\n    }\n    const approvedOutlines = Object.keys(novel.approvals?.outline ?? {}).map(Number);\n    const plan = planDraftBatch({ novel, from, count, availableOutlines, approvedOutlines, force });\n    warnings.push(...plan.warnings);\n\n    // 约束②：上下文预算 ×N —— 没有场景契约就退回串行\n    const contracts = (await io.readJson(p.sceneContracts)) ?? {};\n    const covered = plan.ready.filter((n) => contractFor(contracts, n) !== null).length;\n    let limit = Math.max(1, Math.min(Number.isInteger(concurrency) && concurrency >= 1 ? concurrency : 1, MAX_CONCURRENCY));\n    if (limit > 1 && covered === 0) {\n        warnings.push(`这 ${plan.ready.length} 章都没有场景契约（上下文未裁剪）——已把并发降到 1（novel_scene save 建契约后可提速）`);\n        limit = 1;\n    } else if (limit > 1 && covered < plan.ready.length) {\n        warnings.push(`只有 ${covered}/${plan.ready.length} 章有场景契约，未裁剪的章上下文更重，注意额度`);\n    }\n    if (limit > 1 && plan.ready.length > 1) {\n        warnings.push('并发生成：第 2 章起看不到前面章节的正文（还没写出来），衔接完全依赖细纲——连环悬念章建议单独串行写');\n    }\n\n    // 并发>1 时父锚定**只解析一次**：多章并发各自 agents.resume 同一持久化会话\n    // 有撞宿主持久化写锁的风险（0.13.3 复盘）。解析结果经 run({ parent }) 传给\n    // 每一章。解析失败→并发降 1，让单章路径自己锚定、给出完整的人话诊断。\n    // （typeof 守卫：测试替身引擎可能只实现 run。）\n    let sharedParent;\n    if (limit > 1 && typeof engine.anchor === 'function') {\n        const a = await engine.anchor({ channel: 'draft', sessionId, sessionIds: sessionCandidates, signal });\n        if (a.ok) {\n            sharedParent = a.parent;\n        } else {\n            limit = 1;\n            warnings.push('父会话锚定失败——已把并发降为 1 逐章重试（' + String(a.error?.message ?? a.error).slice(0, 120) + '）');\n        }\n    }\n\n    const emit = (event) => { if (typeof onEvent === 'function') onEvent(event); };\n    const todo = plan.items.filter((i) => !i.blocked);\n\n    // ── 断点检查点（.novel/batch-checkpoint.json，机器状态）──────────────────\n    // 每章提交/被拦后更新；REST `resume:true` 从这里恢复参数。检查点写失败不阻断\n    // 批量（它是便利设施，正确性靠 planDraftBatch 对已落盘章的自动拦截——重跑同\n    // 范围天然跳过已完成的章）。\n    const checkpoint = {\n        book, from, count, concurrency: limit, force: force === true,\n        status: 'running', startedAt: new Date().toISOString(),\n        completed: [], failed: [],\n    };\n    // 并发写守卫（审查 L1）：两个 runDraftBatch 并发时，旧实现的 'auto' 整体覆盖会让\n    // 后启动者把 startedAt 刷成自己的 now——resume 侧的 10 分钟防重入窗口被反复重置，\n    // 面板「续跑」在批次正常结束前一直 409。现在每轮先读盘：盘上是**别人**的运行中\n    // 检查点（startedAt 不同且未过期，与 insights.js resume 侧同一窗口/漂移语义）就让路，\n    // 不动它的文件；自己的写走读时版本 + writeJsonAtVersion 守卫，抢写冲突重读重判一次。\n    const CK_RUNNING_WINDOW_MS = 10 * 60_000;\n    const saveCk = async () => {\n        for (let attempt = 0; attempt < 2; attempt += 1) {\n            try {\n                const { value: cur, version } = await io.readJsonWithVersion(p.batchCheckpoint);\n                if (cur && cur.status === 'running' && cur.startedAt !== checkpoint.startedAt) {\n                    const age = Date.now() - Date.parse(cur.startedAt);\n                    if (Number.isFinite(age) && age >= -60_000 && age < CK_RUNNING_WINDOW_MS) return;\n                }\n                await io.writeJsonAtVersion(p.batchCheckpoint, checkpoint, version);\n                return;\n            } catch (error) {\n                if (!isVersionConflict(error)) return; /* 检查点失败不阻断 */\n                // 冲突：读后写前被人抢先——重读盘上现况再判一次\n            }\n        }\n    };\n    await saveCk();\n\n    // ── 阶段一：并发生成草稿 ────────────────────────────────────────────────\n    const drafts = (\n        await mapWithConcurrency(todo, limit, async (item) => {\n        const n = item.chapter;\n        try {\n            emit({ type: 'draft-start', chapter: n });\n            // audience:'batch' —— 上下文包只有一个实现，但会话纪律段（待批提案/交付/输出预算）\n            // 对单次补全的起草引擎没有读者：它没有工具可调、不向用户汇报。\n            const brief = await buildBriefing({ config: bookConfig, io, book, novel, n, audience: 'batch' });\n            // 落一份依据指纹（与 novel_briefing 同一份记录）：批量是先给所有章建简报、\n            // 再逐章提交，若期间有人改了细纲/契约，提交时就会报「简报已过期」。\n            await recordBasis(io, p, n, brief.basis);\n            const r = await engine.run('draft', {\n                system: draftSystem(bookConfig),\n                prompt: buildDraftPrompt({ chapter: n, briefing: brief.rendered, chapterOutline: brief.chapterOutline }),\n                signal,\n                sessionId,\n                sessionIds: sessionCandidates,\n                ...(sharedParent !== undefined ? { parent: sharedParent } : {}),\n            });\n            if (!r.ok) {\n                emit({ type: 'draft-failed', chapter: n, code: r.error.code });\n                return { chapter: n, ok: false, stage: 'generate', reason: `${r.error.message}（${r.error.advice}）`, error: r.error };\n            }\n            const content = extractChapterText(r.text);\n            if (content === '') {\n                return { chapter: n, ok: false, stage: 'generate', reason: '模型输出里没有可用正文（可能只回了说明）' };\n            }\n            emit({ type: 'draft-done', chapter: n, chars: content.length });\n            return { chapter: n, ok: true, content, chars: content.length, briefingChars: brief.totalChars, briefWarnings: brief.warnings };\n        } catch (error) {\n            return { chapter: n, ok: false, stage: 'generate', reason: String(error?.message ?? error) };\n        }\n    }, { signal })\n    ).map((r, i) => (r instanceof Error\n        ? { chapter: todo[i]?.chapter, ok: false, stage: 'generate', reason: `生成器异常：${r.message}` }\n        : r));\n\n    // ── 阶段二：逐章串行提交（同一条硬约束链）──────────────────────────────\n    // L6 修复：abort 信号会让 mapWithConcurrency 在 results 里留下 undefined 空洞\n    // ——此前空洞走进 !d.ok 被当成失败章，产出没有章号的幽灵结果行。\n    const cancelled = drafts.filter((d) => d === undefined).length;\n    if (cancelled > 0) warnings.push(`有 ${cancelled} 章因取消信号未生成（批次已被中断）`);\n    const results = [];\n    for (const d of drafts) {\n        if (d === undefined) continue;\n        if (!d.ok) {\n            checkpoint.failed.push(d.chapter);\n            await saveCk();\n            results.push({ ...d, committed: false });\n            continue;\n        }\n        const n = d.chapter;\n        const outlineText = (await io.readText(p.chapterOutline(n))) ?? '';\n        const { title, summary } = deriveTitleSummary(outlineText, n);\n        try {\n            emit({ type: 'commit-start', chapter: n });\n            const committed = await commitChapter({\n                config: bookConfig, io, p, book, novel, n,\n                title, content: d.content, summary,\n                castNames: [], updates: [], force: force === true,\n                committedBy: 'agent',\n                engine,\n            });\n            emit({ type: 'commit-done', chapter: n, version: committed.version });\n            checkpoint.completed.push(n);\n            await saveCk();\n            results.push({\n                chapter: n, ok: true, committed: true, title, chars: committed.chars,\n                version: committed.version, path: committed.path,\n                contentGate: committed.contentGate.ok ? 'pass' : 'forced',\n                noai: committed.noai.score,\n                warnings: [...(d.briefWarnings ?? []), ...committed.warnings],\n            });\n        } catch (error) {\n            // 门禁拦下：这一章不落盘，其余照旧（不整批回滚）\n            emit({ type: 'commit-rejected', chapter: n });\n            checkpoint.failed.push(n);\n            await saveCk();\n            results.push({\n                chapter: n, ok: false, committed: false, stage: 'commit',\n                reason: String(error?.message ?? error),\n            });\n        }\n    }\n\n    const committedCount = results.filter((r) => r.committed).length;\n    // 全部尝试章都落盘才算 done；有被拦/取消/未生成 → partial（可 resume 重试）。\n    checkpoint.status = (todo.length === 0 || (results.length === todo.length && results.every((r) => r.ok))) ? 'done' : 'partial';\n    checkpoint.finishedAt = new Date().toISOString();\n    await saveCk();\n    const stats = {\n        planned: count,\n        attempted: todo.length,\n        blockedAtPlan: plan.blocked.length,\n        committed: committedCount,\n        failed: results.length - committedCount,\n    };\n    return { items: plan.items, results, concurrency: limit, warnings, stats };\n}\n"
    }
